"""Lazy min-heap with O(1) insert.

Insert appends to a dirty buffer. The heap property is restored
lazily on the next extract/peek that needs it, by merging the
buffer into the main heap via bulk heapify (O(k) for k dirty items).
Amortized cost of extract_min depends on insert frequency.
"""


class MinHeap:
    __slots__ = ("_heap", "_dirty")

    def __init__(self):
        self._heap: list[int] = []   # satisfies the min-heap invariant
        self._dirty: list[int] = []  # unsorted insertion buffer

    # ---- O(1) operations ----

    def insert(self, value: int) -> None:
        self._dirty.append(value)

    def __len__(self) -> int:
        return len(self._heap) + len(self._dirty)

    def __bool__(self) -> bool:
        return bool(self._heap or self._dirty)

    # ---- operations that may trigger a flush ----

    def peek(self) -> int:
        self._flush()
        return self._heap[0]

    def extract_min(self) -> int:
        self._flush()
        last = self._heap.pop()
        if self._heap:
            min_val = self._heap[0]
            self._heap[0] = last
            self._sift_down(0)
            return min_val
        return last

    # ---- internals ----

    def _flush(self) -> None:
        """Merge the dirty buffer into the main heap in O(n) total."""
        if not self._dirty:
            return
        # Append dirty items then re-heapify the whole array
        self._heap.extend(self._dirty)
        self._dirty.clear()
        # Bottom-up heapify (Floyd's algorithm) – O(n)
        for i in range(len(self._heap) // 2 - 1, -1, -1):
            self._sift_down(i)

    def _sift_down(self, i: int) -> None:
        heap = self._heap
        n = len(heap)
        while True:
            smallest = i
            left = 2 * i + 1
            right = left + 1
            if left < n and heap[left] < heap[smallest]:
                smallest = left
            if right < n and heap[right] < heap[smallest]:
                smallest = right
            if smallest == i:
                break
            heap[i], heap[smallest] = heap[smallest], heap[i]
            i = smallest


if __name__ == "__main__":
    h = MinHeap()
    for v in [5, 3, 8, 1, 2]:
        h.insert(v)  # each insert is O(1)
    print([h.extract_min() for _ in range(len(h))])  # [1, 2, 3, 5, 8]

"""Min-heap with O(1) insert via a lazy dirty buffer.

Insert appends to an unsorted buffer in O(1). The buffer is merged
into the main heap (Floyd's heapify, O(k)) on the next peek/extract.
decrease_key checks the buffer first (O(1) dict lookup) before
falling back to the heap.
"""


class MinHeap:
    __slots__ = ("_heap", "_pos", "_dirty", "_dirty_pos")

    def __init__(self):
        # Main heap: list of [key, value], always satisfies heap invariant
        self._heap: list[list] = []
        self._pos: dict = {}           # value -> index in _heap
        # Dirty buffer: unsorted pending inserts
        self._dirty: list[list] = []
        self._dirty_pos: dict = {}     # value -> index in _dirty

    # ── O(1) operations ──────────────────────────────────────────────

    def insert(self, value, key) -> None:
        """Insert an item with the given key (priority). O(1)."""
        idx = len(self._dirty)
        self._dirty.append([key, value])
        self._dirty_pos[value] = idx

    def __len__(self) -> int:
        return len(self._heap) + len(self._dirty)

    def __bool__(self) -> bool:
        return bool(self._heap or self._dirty)

    # ── Operations that may trigger a flush ──────────────────────────

    def peek(self):
        """Return (key, value) of the minimum element. Amortized O(1)."""
        if not self._heap and not self._dirty:
            raise IndexError("peek from empty heap")
        self._flush()
        return tuple(self._heap[0])

    def extract_min(self):
        """Remove and return (key, value) of the minimum element. Amortized O(log n)."""
        if not self._heap and not self._dirty:
            raise IndexError("extract from empty heap")
        self._flush()
        self._swap(0, len(self._heap) - 1)
        key, value = self._heap.pop()
        del self._pos[value]
        if self._heap:
            self._sift_down(0)
        return (key, value)

    def decrease_key(self, value, new_key) -> None:
        """Decrease the key of the given value. O(log n) or O(1) if in dirty buffer."""
        # Check dirty buffer first – just update in place, no reorder needed
        if value in self._dirty_pos:
            idx = self._dirty_pos[value]
            if new_key > self._dirty[idx][0]:
                raise ValueError("new key is greater than current key")
            self._dirty[idx][0] = new_key
            return

        if value not in self._pos:
            raise KeyError(f"value {value!r} not in heap")
        idx = self._pos[value]
        if new_key > self._heap[idx][0]:
            raise ValueError("new key is greater than current key")
        self._heap[idx][0] = new_key
        self._sift_up(idx)

    # ── Internal helpers ─────────────────────────────────────────────

    def _flush(self) -> None:
        """Merge the dirty buffer into the main heap. O(n) total for n dirty items."""
        if not self._dirty:
            return
        self._heap.extend(self._dirty)
        self._pos.update(self._dirty_pos)
        self._dirty.clear()
        self._dirty_pos.clear()
        # Floyd's bottom-up heapify – O(n)
        for i in range(len(self._heap) // 2 - 1, -1, -1):
            self._sift_down(i)

    def _swap(self, i, j) -> None:
        self._heap[i], self._heap[j] = self._heap[j], self._heap[i]
        self._pos[self._heap[i][1]] = i
        self._pos[self._heap[j][1]] = j

    def _sift_up(self, i) -> None:
        heap = self._heap
        while i > 0:
            parent = (i - 1) // 2
            if heap[i][0] < heap[parent][0]:
                self._swap(i, parent)
                i = parent
            else:
                break

    def _sift_down(self, i) -> None:
        heap = self._heap
        n = len(heap)
        while True:
            smallest = i
            left = 2 * i + 1
            right = 2 * i + 2
            if left < n and heap[left][0] < heap[smallest][0]:
                smallest = left
            if right < n and heap[right][0] < heap[smallest][0]:
                smallest = right
            if smallest != i:
                self._swap(i, smallest)
                i = smallest
            else:
                break


if __name__ == "__main__":
    h = MinHeap()
    h.insert("task_c", 30)
    h.insert("task_a", 10)
    h.insert("task_b", 20)
    h.insert("task_d", 40)

    print("peek:", h.peek())            # (10, 'task_a')
    print("extract:", h.extract_min())  # (10, 'task_a')
    print("extract:", h.extract_min())  # (20, 'task_b')

    h.decrease_key("task_d", 5)
    print("after decrease_key(task_d, 5):")
    print("extract:", h.extract_min())  # (5, 'task_d')
    print("extract:", h.extract_min())  # (30, 'task_c')
